import { beforeEach, expect, it, vi } from 'vitest';
import { EventEmitter } from 'node:events';
import { browserCandidates, listInstalledBrowsers, openInBrowser } from './installed-browsers';

const mocks = vi.hoisted(() => ({ access: vi.fn(), spawn: vi.fn(), external: vi.fn() }));
vi.mock('node:fs/promises', () => ({ access: mocks.access }));
vi.mock('node:child_process', () => ({ spawn: mocks.spawn }));
vi.mock('electron', () => ({ shell: { openExternal: mocks.external } }));
beforeEach(() => {
  vi.clearAllMocks();
  mocks.access.mockRejectedValue(new Error('missing'));
});

it('discovers native locations on all three platforms regardless of test host', () => {
  expect(
    browserCandidates(
      'win32',
      { LOCALAPPDATA: 'C:\\Users\\User\\AppData\\Local', ProgramFiles: 'C:\\Program Files' },
      'C:\\Users\\User',
    ),
  ).toContainEqual({
    id: 'edge',
    name: 'Microsoft Edge',
    path: 'C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe',
  });
  expect(browserCandidates('darwin', {}, '/Users/user')).toContainEqual({
    id: 'chrome',
    name: 'Google Chrome',
    path: '/Users/user/Applications/Google Chrome.app',
  });
  const linux = browserCandidates('linux', { PATH: '/usr/bin:.:relative:/snap/bin' }, '/home/user');
  expect(linux).toContainEqual({
    id: 'chromium',
    name: 'Chromium',
    path: '/snap/bin/chromium-browser',
  });
  expect(linux.every((candidate) => candidate.path.startsWith('/'))).toBe(true);
});

it('lists only installed browsers, deduplicates them, and hides executable paths', async () => {
  mocks.access.mockImplementation(async (path: string) => {
    if (!/google[\\/ -]chrome/i.test(path)) throw new Error('missing');
  });
  expect(await listInstalledBrowsers()).toEqual([{ id: 'chrome', name: 'Google Chrome' }]);
});

it('always supports the default browser and rejects arbitrary executables and schemes', async () => {
  await openInBrowser('default', 'https://voicestudio.sh');
  expect(mocks.external).toHaveBeenCalledWith('https://voicestudio.sh/');
  await expect(openInBrowser('cmd.exe', 'https://example.com')).rejects.toThrow();
  await expect(openInBrowser('default', 'file:///private')).rejects.toThrow();
  expect(mocks.spawn).not.toHaveBeenCalled();
});

it('passes URLs as a single argument to a detected browser without a command shell', async () => {
  mocks.access.mockImplementation(async (path: string) => {
    if (!/google[\\/ -]chrome/i.test(path)) throw new Error('missing');
  });
  mocks.spawn.mockImplementation(() => {
    const child = Object.assign(new EventEmitter(), { unref: vi.fn() });
    queueMicrotask(() => child.emit('spawn'));
    return child;
  });
  await openInBrowser('chrome', 'https://example.com/?q=$(unsafe)&a=2');
  const [, args, options] = mocks.spawn.mock.calls[0];
  expect(args.at(-1)).toBe('https://example.com/?q=$(unsafe)&a=2');
  expect(options.shell).not.toBe(true);
  expect(options.windowsHide).toBe(true);
});

import { mkdtemp, readFile, realpath, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, expect, it } from 'vitest';
import { authorizeModelsDirectory } from './media-authorization';

const roots: string[] = [];
afterEach(async () => {
  await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
});

it('mints one-shot models-directory capabilities only after a writable directory check', async () => {
  const root = await mkdtemp(join(tmpdir(), 'voicestudio-model-dir-'));
  roots.push(root);
  const dataDir = join(root, 'data');
  const selected = join(root, 'model cache');

  const result = await authorizeModelsDirectory(dataDir, selected);
  expect(result.path).toBe(await realpath(selected));
  const payload = JSON.parse(
    await readFile(join(dataDir, '.path-authorizations', `${result.authorization}.json`), 'utf8'),
  );
  expect(payload).toEqual({
    token: result.authorization,
    kind: 'models_dir',
    path: await realpath(selected),
  });
});

it('represents restoring the platform default with an authorized empty path', async () => {
  const root = await mkdtemp(join(tmpdir(), 'voicestudio-model-reset-'));
  roots.push(root);

  const result = await authorizeModelsDirectory(join(root, 'data'), '');
  const payload = JSON.parse(
    await readFile(
      join(root, 'data', '.path-authorizations', `${result.authorization}.json`),
      'utf8',
    ),
  );
  expect(result.path).toBe('');
  expect(payload.path).toBe('');
});

import React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import i18n from '../i18n';
import {
  reduceModelDownloadEvent,
  isAutoPurgeTerminal,
  isTerminalPhase,
  downloadKey,
} from '../components/settings/models/downloadReducer';
import { makeModelColumns } from '../components/settings/models/columns';

const t = i18n.t.bind(i18n);
const REPO = 'org/model';
const KEY = downloadKey('local', REPO);

// ── P1-A: async install errors must be visible, not silently purged ─────────

describe('reduceModelDownloadEvent — install_error persistence (P1-A)', () => {
  it('stores install_error with its mirror-aware message (#890 core/failure.py)', () => {
    const s = reduceModelDownloadEvent(
      {},
      { repo_id: REPO, phase: 'install_error', error: 'boom — mirror hf-mirror.com unreachable' },
    );
    expect(s[KEY].phase).toBe('install_error');
    expect(s[KEY].error).toBe('boom — mirror hf-mirror.com unreachable');
  });

  it('the error survives later unrelated events (never gets wiped)', () => {
    let s = reduceModelDownloadEvent({}, { repo_id: REPO, phase: 'install_start' });
    s = reduceModelDownloadEvent(s, { repo_id: REPO, phase: 'install_error', error: 'disk full' });
    // A stray aggregate for ANOTHER repo must not touch this errored row.
    s = reduceModelDownloadEvent(s, {
      repo_id: 'other/x',
      phase: 'aggregate',
      bytes_done: 1,
      total_bytes: 2,
    });
    expect(s[KEY].phase).toBe('install_error');
    expect(s[KEY].error).toBe('disk full');
  });

  it('ignores keepalive events without a repo_id', () => {
    const prev = { [REPO]: { phase: 'install_error', error: 'x' } };
    expect(reduceModelDownloadEvent(prev, {})).toBe(prev);
  });
});

it('keeps simultaneous local and remote downloads of one repo separate', () => {
  let s = reduceModelDownloadEvent(
    {},
    {
      target: 'local',
      repo_id: REPO,
      phase: 'aggregate',
      bytes_done: 1,
      total_bytes: 10,
    },
  );
  s = reduceModelDownloadEvent(s, {
    target: 'gpu2',
    repo_id: REPO,
    phase: 'aggregate',
    bytes_done: 7,
    total_bytes: 10,
  });
  expect(s[downloadKey('local', REPO)].agg.bytes_done).toBe(1);
  expect(s[downloadKey('gpu2', REPO)].agg.bytes_done).toBe(7);
});

describe('isAutoPurgeTerminal — only success terminals auto-purge (P1-A)', () => {
  it('purges success terminals but NOT install_error', () => {
    expect(isAutoPurgeTerminal('install_done')).toBe(true);
    expect(isAutoPurgeTerminal('delete_done')).toBe(true);
    expect(isAutoPurgeTerminal('install_cancelled')).toBe(true);
    expect(isAutoPurgeTerminal('install_error')).toBe(false);
    expect(isAutoPurgeTerminal('active')).toBe(false);
  });

  it('isTerminalPhase counts install_error (so the list still refetches)', () => {
    expect(isTerminalPhase('install_error')).toBe(true);
    expect(isTerminalPhase('install_done')).toBe(true);
    expect(isTerminalPhase('active')).toBe(false);
  });
});

function renderCell(colId, rt, handlers, mOver = {}) {
  const cols = makeModelColumns({
    t,
    getRowRuntime: () => rt,
    speedRef: { current: {} },
    MODEL_ROLE_LABEL: {},
    onInstall: vi.fn(),
    onDelete: vi.fn(),
    onReinstall: vi.fn(),
    onCancel: vi.fn(),
    onDismissError: vi.fn(),
